def assemble(system_prompt, tools, memory, chunks, history, instruction):
    """Return an Anthropic Messages body with the six layers in the series' order.

    memory and chunks are lists of strings; history is a list of {"role", "content"} turns.
    """
    messages = []
    if memory:
        messages.append({"role": "user", "content": "<memory>" + "\n".join(memory) + "</memory>"})
        messages.append({"role": "assistant", "content": "Acknowledged."})
    if chunks:
        messages.append({"role": "user", "content": "\n".join(f"<chunk>{c}</chunk>" for c in chunks)})
    messages.append({"role": "user", "content": instruction})
    messages.extend(history)
    return {"system": system_prompt, "tools": tools, "messages": messages}

